DROP POLICY "player directory" ON public.social_players;
CREATE POLICY "own player preferences" ON public.social_players FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.social_directory(ids uuid[]) RETURNS TABLE(user_id uuid,handle text,status text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.user_id,p.handle,CASE WHEN p.user_id=auth.uid() THEN p.status WHEN p.status='invisible' OR public.social_blocked(auth.uid(),p.user_id) THEN 'offline' WHEN EXISTS(SELECT 1 FROM social_friends f WHERE f.accepted AND auth.uid() IN(f.sender_id,f.recipient_id) AND p.user_id IN(f.sender_id,f.recipient_id)) THEN p.status ELSE 'offline' END FROM social_players p WHERE auth.uid() IS NOT NULL AND p.user_id=ANY(ids); $$;
REVOKE ALL ON FUNCTION public.social_directory(uuid[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.social_directory(uuid[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.social_blocked(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN auth.uid() IS NOT NULL AND auth.uid() IN(a,b) THEN EXISTS(SELECT 1 FROM social_blocks WHERE (user_id=a AND target_id=b) OR (user_id=b AND target_id=a)) ELSE true END; $$;
CREATE OR REPLACE FUNCTION public.social_member(p uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid()=u AND EXISTS(SELECT 1 FROM social_members WHERE party_id=p AND user_id=u AND joined); $$;
DROP POLICY "party members" ON public.social_members;
CREATE POLICY "party members" ON public.social_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR (joined AND public.social_member(party_id,auth.uid())) OR EXISTS(SELECT 1 FROM social_parties WHERE id=party_id AND owner_id=auth.uid()));
